import 'package:path/path.dart';
import 'package:sqflite/sqflite.dart';
import '../models/invoice.dart';
class DatabaseService{DatabaseService._();static final instance=DatabaseService._();Database? _db;Future<Database> get database async{_db??=await openDatabase(join(await getDatabasesPath(),'invoicepro.db'),version:1,onCreate:(db,_)async{await db.execute('CREATE TABLE invoices (id INTEGER PRIMARY KEY AUTOINCREMENT, invoice_number TEXT NOT NULL, customer_name TEXT NOT NULL, customer_address TEXT, date TEXT NOT NULL, gst_rate REAL NOT NULL)');await db.execute('CREATE TABLE invoice_items (id INTEGER PRIMARY KEY AUTOINCREMENT, invoice_id INTEGER NOT NULL, description TEXT NOT NULL, quantity REAL NOT NULL, rate REAL NOT NULL, FOREIGN KEY(invoice_id) REFERENCES invoices(id) ON DELETE CASCADE)');});return _db!;}Future<int> insertInvoice(Invoice invoice)async{final db=await database;return db.transaction((txn)async{final id=await txn.insert('invoices',invoice.toMap()..remove('id'));for(final item in invoice.items){await txn.insert('invoice_items',item.toMap(id)..remove('id'));}return id;});}Future<List<Invoice>> getInvoices()async{final db=await database;final rows=await db.query('invoices',orderBy:'date DESC,id DESC');final result=<Invoice>[];for(final row in rows){final items=await db.query('invoice_items',where:'invoice_id=?',whereArgs:[row['id']]);result.add(Invoice.fromMap(row,items.map(InvoiceItem.fromMap).toList()));}return result;}}
